# Simple neighbor-based transformation
def neighbor_count_transform(grid):
    result = [[0]*9 for _ in range(9)]
    for r in range(9):
        for c in range(9):
            if grid[r][c] != 0:
                # Count how many cells have the same color as neighbors
                count_same = 0
                count_diff = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 9 and 0 <= nc < 9:
                            val = grid[nr][nc]
                            if val == grid[r][c]:
                                count_same += 1
                            elif val != 0:
                                count_diff += 1
                if count_same > count_diff:
                    result[r][c] = grid[r][c]
                else:
                    result[r][c] = 0
    return result

