# Try another approach: mirror across both axes and combine all positions
def full_symmetry(grid):
    result = [[grid[r][c] for c in range(9)] for r in range(9)]
    # Add horizontal mirror
    for r in range(9):
        for c in range(9):
            result[r][8-c] = grid[r][c]
    # Add vertical mirror of original
    for r in range(9):
        for c in range(9):
            result[8-r][c] = grid[r][c]
    # Add point reflection
    for r in range(9):
        for c in range(9):
            result[8-r][8-c] = grid[r][c]
    return result

